<template>
  <main class="login-page">
    <LanguageSwitcher style="position: fixed; top: 16px; right: 16px; z-index: 20" />
    <section class="visual-panel"><RouterLink to="/" class="brand"><span class="brand-mark"><img src="/logo.png" alt="Cu-Scan logo" /></span><span><strong>Cu-Scan</strong><small>{{ t('brandSubtitle') }}</small></span></RouterLink><div class="visual-content"><p class="eyebrow">{{ t('loginWelcome') }}</p><h1>{{ t('loginHeroTitle') }}<br /><span>{{ t('loginHeroAccent') }}</span></h1><p>{{ t('loginHeroDescription') }}</p><div class="visual-proof"><div><span>95%+</span><small>{{ t('detectionAccuracyLabel') }}</small></div><div><span>&lt; 2s</span><small>{{ t('averageAnalysis') }}</small></div></div></div><div class="visual-card"><div class="card-status"><i></i><span>{{ t('systemReady') }}</span><small>{{ t('aiModelOnline') }}</small></div><div class="card-line"></div><p>{{ t('dashboardReady') }}</p></div></section>
    <section class="login-panel"><div class="login-wrap"><div class="form-heading"><p class="eyebrow">{{ t('signInToCuScan') }}</p><h2>{{ t('goodToSeeYou') }}</h2><p>{{ t('continueWorkspace') }}</p></div><form class="login-form" @submit.prevent="handleLogin" novalidate><div class="field"><label for="email">{{ t('emailAddress') }}</label><input id="email" v-model="email" type="email" autocomplete="email" placeholder="you@example.com" :class="{ error: errors.email }" @input="clearError('email')" /><small v-if="errors.email" class="field-error">{{ errors.email }}</small></div><div class="field"><label for="password">{{ t('password') }}</label><div class="password-wrap"><input id="password" v-model="password" :type="showPassword ? 'text' : 'password'" autocomplete="current-password" :placeholder="t('enterPassword')" :class="{ error: errors.password }" @input="clearError('password')" /><button type="button" class="show-password" :aria-label="t(showPassword ? 'hidePassword' : 'showPassword')" @click="showPassword = !showPassword">{{ t(showPassword ? 'hidePassword' : 'showPassword') }}</button></div><small v-if="errors.password" class="field-error">{{ errors.password }}</small></div><div class="form-options"><label class="remember"><input v-model="rememberMe" type="checkbox" /><span>{{ t('rememberMe') }}</span></label><RouterLink to="/forgot-password">{{ t('forgotPassword') }}</RouterLink></div><p v-if="authStore.error" class="auth-error">{{ authStore.error }}</p><button class="submit-btn" type="submit" :disabled="isSubmitting"><span v-if="!isSubmitting">{{ t('signIn') }} <b>→</b></span><span v-else class="loading"><i></i> {{ t('signingIn') }}</span></button></form><div class="divider"><span></span><em>{{ t('newToCuScan') }}</em><span></span></div><RouterLink to="/register" class="create-account">{{ t('createFreeAccount') }} <b>→</b></RouterLink></div></section>
    <div v-if="showVerificationModal" class="modal-overlay" @click.self="showVerificationModal = false"><section class="verification-modal"><div class="mail-icon">✉</div><h3>{{ t('verifyYourEmail') }}</h3><p>{{ t('verificationSent') }} <strong>{{ email }}</strong>. {{ t('verifyThenReturn') }}</p><button class="modal-primary" @click="resendVerification">{{ t('resendVerificationEmail') }}</button><button class="modal-secondary" @click="showVerificationModal = false">{{ t('close') }}</button></section></div>
  </main>
</template>

<script setup>
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../store/auth'
import { useLanguage } from '../store/language'
import LanguageSwitcher from '../components/LanguageSwitcher.vue'
const router = useRouter(); const authStore = useAuthStore(); const email = ref(''); const password = ref(''); const rememberMe = ref(false); const showPassword = ref(false); const isSubmitting = ref(false); const showVerificationModal = ref(false); const errors = reactive({ email: '', password: '' })
const { t } = useLanguage()
onMounted(() => { authStore.initializeAuth(); authStore.clearError(); const savedEmail = localStorage.getItem('rememberedEmail'); if (savedEmail) { email.value = savedEmail; rememberMe.value = true } })
const validateForm = () => { errors.email = ''; errors.password = ''; let valid = true; if (!email.value) { errors.email = t('emailRequired'); valid = false } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)) { errors.email = t('validEmailRequired'); valid = false }; if (!password.value) { errors.password = t('passwordRequired'); valid = false } else if (password.value.length < 6) { errors.password = t('passwordMinimum'); valid = false }; return valid }
const clearError = field => { errors[field] = ''; authStore.clearError() }
const handleLogin = async () => { if (!validateForm()) return; isSubmitting.value = true; if (rememberMe.value) localStorage.setItem('rememberedEmail', email.value); else localStorage.removeItem('rememberedEmail'); const result = await authStore.login(email.value, password.value); if (result.success) router.push('/dashboard'); else if (result.message?.includes('verify your email')) showVerificationModal.value = true; isSubmitting.value = false }
const resendVerification = async () => { await authStore.resendVerificationEmail(email.value) }
</script>

