s:9px 1fr auto; gap:8px; align-items:center; font-size:.73rem; font-weight:750; }.card-status i { width:7px; height:7px; background:#63e5a8; border-radius:50%; box-shadow:0 0 0 4px rgba(99,229,168,.14); }.card-status small { color:#8fb7a4; font-size:.62rem; font-weight:500; }.card-line { height:5px; overflow:hidden; background:rgba(255,255,255,.1); border-radius:99px; }.card-line::after { content:''; display:block; width:72%; height:100%; background:linear-gradient(90deg,#4ed89a,#a1f2c8); border-radius:inherit; }.visual-card p { margin:0; color:#94b9a8; font-size:.71rem; line-height:1.5; }.login-panel { display:grid; place-items:center; padding:48px 28px; }.login-wrap { width:min(100%,440px); }.form-heading { margin-bottom:34px; }.form-heading .eyebrow { color:#128761; }.form-heading h2 { margin:0; color:#132b23; font-size:2rem; line-height:1.13; letter-spacing:-.045em; }.form-heading > p:last-child { margin:10px 0 0; color:#6b8177; font-size:.92rem; }.login-form { display:grid; gap:19px; }.field { display:grid; gap:7px; }.field label { color:#29463a; font-size:.8rem; font-weight:750; }.field input { width:100%; height:48px; padding:0 13px; color:#19352a; background:#fff; border:1px solid #d8e6df; border-radius:11px; outline:none; transition:border .18s,box-shadow .18s; }.field input::placeholder { color:#9aaca3; }.field input:focus { border-color:#16986d; box-shadow:0 0 0 4px rgba(22,152,109,.11); }.field input.error { border-color:#e15858; }.password-wrap { position:relative; }.password-wrap input { padding-right:58px; }.show-password { position:absolute; top:50%; right:7px; padding:5px 7px; color:#14815e; background:transparent; box-shadow:none; font-size:.72rem; font-weight:800; transform:translateY(-50%); }.show-password:hover { color:#075d42; box-shadow:none; transform:translateY(-50%); }.field-error,.auth-error { color:#c33e45; font-size:.73rem; }.form-options { display:flex; justify-content:space-between; align-items:center; margin-top:-1px; }.form-options a { color:#087757; font-size:.76rem; font-weight:750; text-decoration:none; }.remember { display:flex; align-items:center; gap:8px; color:#647d72; font-size:.76rem; cursor:pointer; }.remember input { width:15px; height:15px; accent-color:#14936a; }.auth-error { margin:0; padding:10px 12px; background:#fff2f2; border-radius:9px; }.submit-btn { height:50px; display:grid; place-items:center; padding:0 18px; color:#fff; background:linear-gradient(110deg,#087656,#18a878); border-radius:11px; box-shadow:0 10px 22px rgba(13,128,91,.18); font-size:.9rem; font-weight:800; }.submit-btn:hover:not(:disabled) { box-shadow:0 14px 28px rgba(13,128,91,.26); transform:translateY(-1px); }.submit-btn:disabled { opacity:.7; }.submit-btn b { margin-left:7px; font-size:1.1rem; }.loading { display:flex; align-items:center; gap:8px; }.loading i { width:14px; height:14px; border:2px solid rgba(255,255,255,.4); border-top-color:#fff; border-radius:50%; animation:spin .75s linear infinite; }@keyframes spin { to { transform:rotate(360deg) } }.divider { display:flex; align-items:center; gap:11px; margin:25px 0 16px; color:#82988d; }.divider span { flex:1; height:1px; background:#e0ebe5; }.divider em { font-style:normal; font-size:.72rem; }.create-account { display:flex; justify-content:center; gap:7px; padding:12px; color:#087757; background:#eff9f3; border:1px solid #d8eee1; border-radius:10px; font-size:.79rem; font-weight:800; text-decoration:none; transition:background .2s,transform .2s; }.create-account:hover { background:#e2f5e9; transform:translateY(-1px); }.create-account b { transition:transform .2s; }.create-account:hover b { transform:translateX(3px); }.modal-overlay { position:fixed; inset:0; z-index:2000; display:grid; place-items:center; padding:20px; background:rgba(5,31,24,.56); backdrop-filter:blur(6px); }.verification-modal { width:min(100%,390px); padding:34px; background:#fff; border-radius:20px; box-shadow:0 24px 70px rgba(0,0,0,.22); text-align:center; }.mail-icon { width:5